text:
.host-runtime-status {
  box-sizing: border-box;
  display: grid;
  right: max(1rem, env(safe-area-inset-right));
  bottom: max(1rem, env(safe-area-inset-bottom));
  max-width: min(30rem, calc(100vw - 2rem - env(safe-area-inset-left) - env(safe-area-inset-right)));
  overflow-wrap: break-word;
  pointer-events: none;
}

.native-planet-app {
  min-height: 100dvh;
  background: var(--violet-950);
}

.native-planet-panel {
  position: fixed;
  z-index: 1100;
  inset: 0;
  display: flex;
  flex-direction: column;
  /* The outer frame must never scroll when a reader descendant is revealed. */
  overflow: clip;
  color: var(--violet-950);
  background: var(--paper, #fff8eb);
  padding: env(safe-area-inset-top, 0px) env(safe-area-inset-right, 0px)
    env(safe-area-inset-bottom, 0px) env(safe-area-inset-left, 0px);
}
.native-planet-panel[hidden] { display: none; }
.native-planet-panel__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-shrink: 0;
  gap: 16px;
  padding: 12px 20px;
  border-bottom: 1px solid var(--line, #dccfc0);
}
.native-planet-panel__header h1 { margin: 0; font-size: 1.25rem; }
.native-planet-panel__header .interface-language-control {
  margin-left: auto;
  height: auto;
  padding: 2px;
  background: #eadfef;
  border-color: #c9b7d3;
}
.native-planet-panel__header .interface-language-control button {
  min-width: 44px;
  min-height: 44px;
  color: var(--violet-950);
}
.native-planet-panel__header .interface-language-control button:focus-visible {
  outline: 2px solid var(--violet-950);
  outline-offset: 2px;
}
.native-planet-panel__content { min-height: 0; overflow: auto; overscroll-behavior: contain; }
.native-planet-panel .book-archive-section { padding: 24px clamp(12px, 3vw, 40px); }
.native-planet-panel .recent-history {
  margin: 12px clamp(12px, 3vw, 40px);
  padding: 12px 16px;
}
.native-planet-panel .recent-history > summary { box-sizing: border-box; min-height: 44px; }

/* Retain the canonical brand in the existing phone toolbar and keep all six
   controls at least 44px wide, including both production locale buttons. */
@media (max-width: 720px) {
  .native-planet-app .atlas-experience-surface[data-atlas-view="immersive"] .atlas-immersive-chrome {
    grid-template-columns: 26px minmax(0, 1fr);
    gap: 0;
  }

  .native-planet-app .atlas-experience-surface[data-atlas-view="immersive"] .atlas-immersive-identity {
    display: grid;
    grid-template-columns: 24px;
    justify-content: center;
    width: 26px;
    gap: 0;
    padding: 0;
    border-right: 0;
  }

  .native-planet-app .atlas-experience-surface[data-atlas-view="immersive"] .atlas-immersive-identity > img {
    width: 24px;
    height: 24px;
  }

  .native-planet-app .atlas-experience-surface[data-atlas-view="immersive"] .atlas-immersive-identity > div {
    display: none;
  }

  .native-planet-app .atlas-experience-surface[data-atlas-view="immersive"] .atlas-immersive-chrome nav {
    padding-inline: 0;
  }

  .native-planet-app .atlas-experience-surface[data-atlas-view="immersive"] .interface-language-control button {
    width: 44px;
    min-width: 44px;
    flex: 0 0 44px;
  }
}

@media (min-width: 1100px) {
  .native-planet-panel {
    left: auto;
    width: min(820px, 78vw);
    box-shadow: -24px 0 80px #11031d66;
  }
}
